export function pairSource(){return {version:1,model:'uniform-two-six-v1',slots:[...slots],labels:{sun:'Sun',moon:'Moon'},rules:{keep:'Keep the first seed out. Draw the second from the five positions still in the bag. Refill all six before the next pair.',return:'Put the first seed back. Draw the second from all six positions again. Refill all six before the next pair.'},learn:[line('Chance runs from 0, impossible, to 1, certain. Count favorable positions out of all available positions.'),line('A different example bag has 1 sun and 2 moon. Draw two without returning the first.'),line('After a sun first, only the two moons remain. The chance of a second sun is 0/2.'),line('Sun then sun in that different bag is 1/3 × 0/2 = 0. Both steps must happen along a path, so multiply. Join different paths by adding.',[[1,0],[3,2]])],order:tasks.map(t=>t.id),tasks:Object.fromEntries(tasks.map(t=>[t.id,structuredClone(t)]))};}
